package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Today mascot: a dachshund asleep because nothing is scheduled.
 *
 * The only pose of the three that is resting rather than waiting. Today is the
 * screen with nothing left on it, so the dog has stopped.
 *
 * Exported from the board, node `879:6016`. Its coordinates are the artwork's
 * own; the group offset places it inside the frame the board draws it in, which
 * is what sets the gap to the headline underneath. [MascotImage] explains why
 * the paths are built in Kotlin, and which colour role each tone takes.
 */
@Composable
internal fun TodayMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::sleepingDachshund
    )
}

private const val MascotWidth = 280f
private const val MascotHeight = 102.308f

private fun sleepingDachshund(pale: Color, body: Color, detail: Color): ImageVector =
    ImageVector.Builder(
        name = "TodaySleepingDachshund",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = MascotWidth,
        viewportHeight = MascotHeight
    )
        .addGroup(translationX = ArtworkOffsetX, translationY = ArtworkOffsetY)
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(body)
        )
        .addPath(
            pathData = addPathNodes(PawBack),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(PawFront),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Ear),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Eye),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(ZSmall),
            fill = SolidColor(body)
        )
        .addPath(
            pathData = addPathNodes(ZMedium),
            fill = SolidColor(body)
        )
        .addPath(
            pathData = addPathNodes(ZLarge),
            fill = SolidColor(body)
        )
        .clearGroup()
        .build()

/** Where the artwork sits inside the frame the board draws it in. */
